"use client";

// Browser side of Grok Voice: mic -> PCM16 -> xAI realtime WebSocket -> spoken answer.
// Grok calls get_hazards and we answer with the same hazards JSON the cards show.

import { useCallback, useEffect, useRef, useState } from "react";
import { GET_HAZARDS_TOOL, VOICE, VOICE_INSTRUCTIONS, XAI_REALTIME_URL, realtimeProtocols } from "./config";

export type VoiceStatus = "idle" | "connecting" | "listening" | "thinking" | "speaking" | "error";
export type TranscriptLine = { role: "user" | "assistant"; text: string };

type RealtimeEvent = { type: string; [key: string]: unknown };

const CHUNK_MS = 100;

// Copies mic samples off the audio thread. Inlined so there is no extra file to serve.
const WORKLET_SOURCE = `
class MicTap extends AudioWorkletProcessor {
  process(inputs) {
    const ch = inputs[0] && inputs[0][0];
    if (ch) this.port.postMessage(ch.slice(0));
    return true;
  }
}
registerProcessor("mic-tap", MicTap);
`;

function floatToPcm16Base64(samples: Float32Array): string {
  const bytes = new Uint8Array(samples.length * 2);
  const view = new DataView(bytes.buffer);
  for (let i = 0; i < samples.length; i++) {
    const s = Math.max(-1, Math.min(1, samples[i]));
    view.setInt16(i * 2, s < 0 ? s * 0x8000 : s * 0x7fff, true);
  }
  let bin = "";
  for (let i = 0; i < bytes.length; i += 0x8000) bin += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  return btoa(bin);
}

function pcm16Base64ToFloat(b64: string): Float32Array {
  const bin = atob(b64);
  const out = new Float32Array(bin.length / 2);
  for (let i = 0; i < out.length; i++) {
    let v = bin.charCodeAt(i * 2) | (bin.charCodeAt(i * 2 + 1) << 8);
    if (v >= 0x8000) v -= 0x10000;
    out[i] = v / 0x8000;
  }
  return out;
}

export function useGrokVoice(getHazards: () => unknown) {
  const [status, setStatus] = useState<VoiceStatus>("idle");
  const [transcript, setTranscript] = useState<TranscriptLine[]>([]);
  const [error, setError] = useState<string | null>(null);

  const wsRef = useRef<WebSocket | null>(null);
  const ctxRef = useRef<AudioContext | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const nodesRef = useRef<AudioNode[]>([]);
  const playingRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const playheadRef = useRef(0);
  const readyRef = useRef(false);
  const configuredRef = useRef(false);
  const toolOutputPendingRef = useRef(false);
  const getHazardsRef = useRef(getHazards);
  useEffect(() => {
    getHazardsRef.current = getHazards;
  }, [getHazards]);

  const send = (event: RealtimeEvent) => {
    const ws = wsRef.current;
    if (ws && ws.readyState === WebSocket.OPEN) ws.send(JSON.stringify(event));
  };

  const appendLine = (role: TranscriptLine["role"], text: string, merge: boolean) =>
    setTranscript((prev) => {
      const last = prev[prev.length - 1];
      if (merge && last?.role === role) return [...prev.slice(0, -1), { role, text: last.text + text }];
      return [...prev, { role, text }];
    });

  const stopPlayback = () => {
    for (const src of playingRef.current) {
      try {
        src.stop();
      } catch {}
    }
    playingRef.current.clear();
    playheadRef.current = 0;
  };

  const playChunk = (b64: string) => {
    const ctx = ctxRef.current;
    if (!ctx) return;
    const samples = pcm16Base64ToFloat(b64);
    const buf = ctx.createBuffer(1, samples.length, ctx.sampleRate);
    buf.getChannelData(0).set(samples);
    const src = ctx.createBufferSource();
    src.buffer = buf;
    src.connect(ctx.destination);
    const startAt = Math.max(playheadRef.current, ctx.currentTime + 0.02);
    src.start(startAt);
    playheadRef.current = startAt + buf.duration;
    playingRef.current.add(src);
    src.onended = () => {
      playingRef.current.delete(src);
      if (playingRef.current.size === 0 && readyRef.current) setStatus((s) => (s === "speaking" ? "listening" : s));
    };
  };

  const stop = useCallback(() => {
    readyRef.current = false;
    configuredRef.current = false;
    stopPlayback();
    wsRef.current?.close();
    wsRef.current = null;
    nodesRef.current.forEach((n) => n.disconnect());
    nodesRef.current = [];
    streamRef.current?.getTracks().forEach((t) => t.stop());
    streamRef.current = null;
    ctxRef.current?.close().catch(() => {});
    ctxRef.current = null;
    setStatus((s) => (s === "error" ? s : "idle"));
  }, []);

  const handleEvent = (ev: RealtimeEvent, sampleRate: number) => {
    switch (ev.type) {
      case "conversation.created":
      case "session.created":
        if (!configuredRef.current) {
          configuredRef.current = true;
          send({
            type: "session.update",
            session: {
              voice: VOICE,
              instructions: VOICE_INSTRUCTIONS,
              turn_detection: { type: "server_vad" },
              audio: {
                input: { format: { type: "audio/pcm", rate: sampleRate } },
                output: { format: { type: "audio/pcm", rate: sampleRate } },
              },
              tools: [GET_HAZARDS_TOOL],
            },
          });
        }
        break;
      case "session.updated":
        readyRef.current = true;
        setStatus("listening");
        break;
      case "input_audio_buffer.speech_started":
        stopPlayback(); // let the user interrupt Grok
        setStatus("listening");
        break;
      case "input_audio_buffer.speech_stopped":
        setStatus("thinking");
        break;
      case "conversation.item.added":
      case "conversation.item.created": {
        const item = ev.item as { role?: string; content?: { type: string; transcript?: string }[] } | undefined;
        const said = item?.role === "user" ? item.content?.find((c) => c.type === "input_audio" && c.transcript)?.transcript : undefined;
        if (said) appendLine("user", said, false);
        break;
      }
      case "conversation.item.input_audio_transcription.completed":
        if (typeof ev.transcript === "string" && ev.transcript) appendLine("user", ev.transcript, false);
        break;
      case "response.output_audio.delta":
        if (typeof ev.delta === "string") {
          setStatus("speaking");
          playChunk(ev.delta);
        }
        break;
      case "response.output_audio_transcript.delta":
        if (typeof ev.delta === "string") appendLine("assistant", ev.delta, true);
        break;
      case "response.function_call_arguments.done": {
        if (ev.name !== GET_HAZARDS_TOOL.name) break;
        const hazards = getHazardsRef.current();
        send({
          type: "conversation.item.create",
          item: {
            type: "function_call_output",
            call_id: ev.call_id,
            output: JSON.stringify(hazards ?? { error: "No address has been looked up yet." }),
          },
        });
        toolOutputPendingRef.current = true;
        setStatus("thinking");
        break;
      }
      case "response.done":
        // Ask for the spoken answer only after the response that made the tool call has finished.
        if (toolOutputPendingRef.current) {
          toolOutputPendingRef.current = false;
          send({ type: "response.create" });
        } else if (playingRef.current.size === 0) {
          setStatus("listening");
        }
        break;
      case "error": {
        const e = ev.error as { message?: string } | undefined;
        console.error("[grok-voice]", ev);
        setError(e?.message || "Grok Voice error");
        break;
      }
    }
  };

  const start = useCallback(async () => {
    if (wsRef.current) return;
    setError(null);
    setStatus("connecting");
    try {
      const res = await fetch("/api/voice-token", { method: "POST" });
      if (!res.ok) throw new Error((await res.json().catch(() => ({}))).error || "Could not start voice");
      const { token } = (await res.json()) as { token: string };

      const ctx = new AudioContext();
      ctxRef.current = ctx;
      const stream = await navigator.mediaDevices.getUserMedia({
        audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true },
      });
      streamRef.current = stream;

      const url = URL.createObjectURL(new Blob([WORKLET_SOURCE], { type: "application/javascript" }));
      await ctx.audioWorklet.addModule(url);
      URL.revokeObjectURL(url);
      const source = ctx.createMediaStreamSource(stream);
      const tap = new AudioWorkletNode(ctx, "mic-tap");
      const mute = ctx.createGain();
      mute.gain.value = 0; // keep the graph running without echoing the mic
      source.connect(tap).connect(mute).connect(ctx.destination);
      nodesRef.current = [source, tap, mute];

      const chunkSize = Math.round((ctx.sampleRate * CHUNK_MS) / 1000);
      let pending: Float32Array[] = [];
      let pendingLen = 0;
      tap.port.onmessage = (e: MessageEvent<Float32Array>) => {
        if (!readyRef.current) return;
        pending.push(e.data);
        pendingLen += e.data.length;
        if (pendingLen < chunkSize) return;
        const chunk = new Float32Array(pendingLen);
        let off = 0;
        for (const p of pending) {
          chunk.set(p, off);
          off += p.length;
        }
        pending = [];
        pendingLen = 0;
        send({ type: "input_audio_buffer.append", audio: floatToPcm16Base64(chunk) });
      };

      const ws = new WebSocket(XAI_REALTIME_URL, realtimeProtocols(token));
      wsRef.current = ws;
      ws.onmessage = (m) => {
        try {
          handleEvent(JSON.parse(m.data as string), ctx.sampleRate);
        } catch (err) {
          console.error("[grok-voice] bad event", err);
        }
      };
      ws.onerror = () => setError("Lost the connection to Grok Voice");
      ws.onclose = () => {
        if (wsRef.current === ws) {
          wsRef.current = null;
          stop();
        }
      };
    } catch (err) {
      setError(err instanceof Error ? err.message : String(err));
      setStatus("error");
      stop();
    }
    // handleEvent reads only refs and stable setters
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [stop]);

  useEffect(() => stop, [stop]);

  return { status, transcript, error, start, stop, active: status !== "idle" && status !== "error" };
}
